def icon(name):
    shapes={
        'home':'<path d="m3 10 9-7 9 7v10H3Z"/><path d="M9 20v-7h6v7"/>',
        'book':'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 7h8M8 11h6M4 17h16"/>',
        'save':'<path d="M6 3h12v18l-6-4-6 4Z"/>',
        'search':'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
        'sun':'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',
        'close':'<path d="m6 6 12 12M6 18 18 6"/>',
        'moon':'<path d="M20.5 14A9 9 0 0 1 10 3.5 9 9 0 1 0 20.5 14Z"/>',
        'arrow':'<path d="M5 12h14m-6-6 6 6-6 6"/>',
        'play':'<path d="m9 5 11 7-11 7Z"/>',
        'spark':'<path d="M12 2q0 10 10 10-10 0-10 10 0-10-10-10 10 0 10-10Z"/>',
        'grid':'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',
    }
    return f'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">{shapes[name]}</svg>'

