    body+='</div></section><section class="shell section" id="hikoya" style="padding-top:0"><div class="lola-quote"><h2>Yaxshi kun —<br>o‘zingiz yaratgan kun.</h2><button class="btn pressable" data-request="Lola studiyasi bilan tanishuv">Studiyaga kelish ↗</button></div></section></main>'+footer('Lola Studio')
    return dict(id='07',name='Lola',file='07-lola.html',category='Serif / ijodiy studiya',color='#c44828',background='#fff0e3',summary='Fraunces serif va DM Sans juftligi. Tiniq terrakota, krem va och yashil; iliq, esda qoladigan kompozitsiya.',features='Mahorat darsi tanlash · ariza · bosilish holatli tugmalar',use='Madaniyat, hunarmandchilik, ijod, ta’lim va tadbirlar',style=css,body=body,extra='<script src="extra.js"></script>',fonts=['fraunces','dm-sans'])

