    variants[3]['style'] += '.mono-service{display:flex;flex-direction:column}.mono-service .btn{margin-top:auto;color:#a13b18}.mono-service p{min-height:0}.map-label{max-width:calc(100% - 44px);line-height:1.6}.mono-code{font-size:12px}@media(max-width:420px){.mono-hero h1{font-size:32px;letter-spacing:-1.7px}.mono-bar{font-size:11px;gap:12px}.mono-bar b{font-size:22px}.mono-message h2{font-size:22px}.section-head h2{overflow-wrap:anywhere}}' 
